import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show TargetPlatform, defaultTargetPlatform, kIsWeb;

/// Firebase configuration for the academy's project.
///
/// Written out rather than generated by `flutterfire configure`, which needs
/// an interactive Google sign-in. The values come from the project's own
/// `google-services.json`, which the Android build also reads directly - so
/// the two cannot disagree.
///
/// None of this is secret: the API key identifies the project to Google and
/// is restricted by the app's package name and signing certificate, not by
/// being hidden. The service-account key, which *is* secret, lives only on
/// the server.
class DefaultFirebaseOptions {
  const DefaultFirebaseOptions._();

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyD2USrlHyppN3fHsNLeQhx6EFnNDK805Sw',
    appId: '1:1062268474760:android:b9c48226caea52fab4d63d',
    messagingSenderId: '1062268474760',
    projectId: 'tabala-academy',
    storageBucket: 'tabala-academy.firebasestorage.app',
  );

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError('The academy app does not target the web.');
    }

    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        // Register an iOS app in the Firebase console and add its options
        // here before building for iOS - there is no Mac in this project's
        // toolchain yet, so nothing would exercise a guess.
        throw UnsupportedError(
          'iOS is not configured for Firebase yet - register the bundle id '
          'com.tabalahacademy.app in the Firebase console first.',
        );
      default:
        throw UnsupportedError(
          'Push is not configured for $defaultTargetPlatform.',
        );
    }
  }
}
